// Simplified ONNX Runtime Web placeholder
// This provides a minimal ort object that won't break the worker

(function() {
  'use strict';
  
  // Create a minimal ort object
  const ort = {
    InferenceSession: {
      create: async function(modelPath, options) {
        console.log('ONNX model requested:', modelPath);
        // Simulate model loading failure to trigger heuristic fallback
        throw new Error('Model not available - using heuristic fallback');
      }
    },
    env: {
      wasm: {
        wasmPaths: '/vendor/'
      }
    }
  };
  
  // Make ort available globally
  if (typeof self !== 'undefined') {
    self.ort = ort;
  }
  
  console.log('ONNX Runtime placeholder loaded');
})();